{"content":"import numpy as np

def cross(m,r,R,h):
 z=np.exp(2j*np.pi*np.arange(m)/m)
 D=h+np.sqrt(h*h+abs(R*z-r)**2)
 C=np.polynomial.polynomial.polyfromroots(1/np.conj((R*z-r)/D))
 C=C/C[0]
 E=np.polynomial.polynomial.polyfromroots(-(R-r*z)/D)
 return np.real_if_close(C),np.real_if_close(E)
for m in range(1,9):
 C,E=cross(m,1,2,1)
 print(m,'A',np.round(C,5),'B',np.round(E,5))
 print('ratios',np.round(C/E,5))
"}

